package local.krasview.tv;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

public class SourceBrowserActivity extends TvActivity {
    final ExecutorService network=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());final ArrayDeque<Screen> stack=new ArrayDeque<>();
    MediaSource source;Media.Query query;LinearLayout column,list;TextView status;boolean alive=true;int generation;
    static final class Screen {String title,reference,voice="",identity="";Media.Browse data;int selected;Screen(String t,String r){title=t;reference=r;}}
    @Override public void onCreate(Bundle b){super.onCreate(b);try{source=SourceRegistry.find(this,getIntent().getStringExtra("playback_source"));query=SourceJson.query(getIntent().getStringExtra("query"));stack.push(new Screen(source.name()+" · "+query.title,null));render();load();}catch(Exception e){finish();}}
    void render(){Screen screen=stack.peek();column=new LinearLayout(this);column.setOrientation(1);column.setBackgroundColor(BG);column.setPadding(d(30),d(24),d(30),d(24));setContentView(column);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);column.addView(header);TextView back=button("←  Назад");header.addView(back,new LinearLayout.LayoutParams(d(150),d(48)));back.setOnClickListener(v->onBackPressed());TextView title=text(screen.title,25,TEXT);title.setPadding(d(24),0,0,0);title.setMaxLines(2);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));status=text("Загрузка…",16,MUTED);status.setPadding(0,d(18),0,d(18));column.addView(status);ScrollView scroll=new ScrollView(this);column.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);if(screen.data!=null)show();}
    void load(){int ticket=++generation;Screen screen=stack.peek();status.setText("Загрузка…");network.execute(()->{try{Media.Browse data=source.browse(query,screen.reference);main.post(()->{if(alive&&ticket==generation){screen.data=data;show();}});}catch(Exception e){main.post(()->{if(alive&&ticket==generation){status.setText(e instanceof java.io.IOException?e.getMessage():"Источник вернул неподдерживаемые данные.");list.removeAllViews();TextView retry=button("Повторить");list.addView(retry,new LinearLayout.LayoutParams(d(220),d(52)));retry.setOnClickListener(v->load());retry.requestFocus();}});}});}
    void show(){Screen screen=stack.peek();list.removeAllViews();status.setText(!screen.data.notice.isEmpty()?screen.data.notice:screen.data.items.isEmpty()?"Нет доступных вариантов":"Выбери провайдера, озвучку или видео");for(int i=0;i<screen.data.items.size();i++){final int index=i;Media.Item item=screen.data.items.get(i);TextView row=button(item.title+(item.kind==Media.Kind.FOLDER?"   ›":""));row.setGravity(Gravity.CENTER_VERTICAL);row.setMaxLines(2);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,d(60));lp.bottomMargin=d(10);list.addView(row,lp);row.setOnFocusChangeListener((v,on)->{v.setBackground(shape(on?ACCENT:PANEL,0));row.setTextColor(on?BG:TEXT);if(on)screen.selected=index;});row.setOnClickListener(v->{if(item.kind==Media.Kind.FOLDER){Screen child=new Screen(item.title,item.reference);child.identity=screen.identity+"/"+item.key;child.voice=screen.voice;try{String voice=new org.json.JSONObject(item.reference).optString("voice_name");if(!voice.isEmpty())child.voice=voice;}catch(Exception ignored){}stack.push(child);render();load();}else{try{org.json.JSONObject value=new org.json.JSONObject(item.reference);if(!value.has("voice_name")&&!screen.voice.isEmpty())value.put("voice_name",screen.voice);Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("playback_source",source.id());intent.putExtra("query",SourceJson.query(query));intent.putExtra("source_reference",value.toString());intent.putExtra("position_key",source.id()+":"+query.address+":"+Integer.toHexString((screen.identity+"/"+item.key).hashCode()));intent.putExtra("title",query.title+" — "+item.title);intent.putExtra("film",getIntent().getStringExtra("film"));startActivity(intent);}catch(Exception e){Toast.makeText(this,"Не удалось открыть этот вариант.",Toast.LENGTH_SHORT).show();}}});}if(list.getChildCount()>0)list.getChildAt(Math.min(screen.selected,list.getChildCount()-1)).requestFocus();}
    @Override public void onBackPressed(){generation++;if(stack.size()>1){stack.pop();render();if(stack.peek().data==null)load();}else finish();}
    @Override protected void onDestroy(){alive=false;generation++;main.removeCallbacksAndMessages(null);network.shutdownNow();super.onDestroy();}
}
